BY_LEVEL: dict[str, list[dict]] = {"N5": N5, "N4": N4, "N3": N3, "N2": N2, "N1": N1}


def patterns_for(level: str) -> set[str]:
    """Every grammar pattern the catalogue teaches at `level`."""
    return {p["pattern"] for p in GRAMMAR_POINTS_BY_LEVEL.get(level, [])}


# The languages every row carries a translation in (plan 192).
LANGS = ("en", "fr")


def translation(row: dict, lang: str) -> tuple[str, str]:
    """(text, its language) of a row's translation for a reader of
    `lang`: the row's own when it carries one, else the English, so a
    reader of a language the bank does not hold is still told which
    language they are reading."""
    if lang in LANGS and row.get(lang):
        return row[lang], lang
    return row["en"], "en"


def phrase_key(jp: str) -> str:
    """A short stable name for a sentence (plan 192). A run sends back
    the sentences it has served so the next batch does not repeat them;
    sent as text, sixty N1 sentences outgrew what a URL may carry."""
    return hashlib.sha1(jp.encode("utf-8")).hexdigest()[:10]


# ── Plan 192: a level's sentences use the level ──────────────────
# The levels whose sentences must bring their own vocabulary. N5 is not
# one of them: every word an N5 sentence can use is N5 or kana, and its
# rows are pinned by the basics course, 入門 and the ride.
GRADED_LEVELS = ("N4", "N3", "N2", "N1")
# Deck words of the sentence's own level, besides the point's own words.
LEVEL_WORDS_MIN = 2


def _is_numeral(surface: str) -> bool:
    """三十, 三千, 二十: a number the tokenizer leaves as one noun the deck
    has no card for, and that no learner needs one for."""
    return bool(surface) and all(c in "〇一二三四五六七八九十百千万億0123456789０１２３４５６７８９" for c in surface)


def off_deck_words(jp: str) -> list[str]:
    """Content words the breakdown finds no deck card for -- a JMdict
    pool word (no level: the course never teaches it) or no match at
    all -- leaving out a word a grammar point owns (the point is its
    explanation) and a numeral. study/level_mix's own off_deck reads the
    tokenizer's morphemes rather than the breakdown and so names every
    しまっ and いただけ a point has already explained."""
    from study import difficulty
    from study.analysis import CONTENT_POS, analyze_local

    out = []
    for tok in analyze_local(jp)["tokens"]:
        if tok["pos"] not in CONTENT_POS or tok.get("grammar"):
            continue
        match = tok.get("vocab_match")
        if match and not match.get("pool"):
            continue
        if tok.get("parts") and all(part["vocab_match"] or part["pos"] not in CONTENT_POS
                                    or difficulty.word_level(part["lemma"]) for part in tok["parts"]):
            # An idiom the pool reads whole and the deck's words make
            # (手に入れる: 手, 入れる; 身につける's つける, which the deck
            # has under more than one kanji), plan 272, or a run of its
            # nouns the dictionary writes as one word, a prefix on them
            # no word (電話番号, 立候補), plan 276.
            continue
        surface = tok["surface"]
        if _is_numeral(surface) or difficulty.word_level(surface) or difficulty.word_level(tok.get("lemma", "")):
            continue
        if tok.get("number") is not None:
            # A number with its counter read as one word -- the ordinal
            # 三度目, the age １０代 (plan 272) -- is its figure's.
            continue
        out.append(surface)
    return out


def deck_gaps(jp: str, pattern: str) -> list[str]:
    """Content words the vocab audit counts as having no card
    (scripts/audit_vocab_deck's corpus, whose ratchets
    tests/test_audit_vocab_deck.py holds): the audit's own measure, so
    the two cannot drift. The claimed point's own words (余儀 in
    〜を余儀なくされる) and a word the point builds (支えあう for 〜あう,
    書きかけ for 〜かける) are the point's demonstration and are not
    counted against the row, nor is a name or a numeral."""
    from scripts.audit_vocab_deck import IGNORED_LEMMAS, _classify, _resolve_tokens
    from study.analysis import CONTENT_POS
    from study.grammar_match import stems

    built = [s for s in stems(pattern) if s]
    out = []
    for m, hit in _resolve_tokens(jp):
        if hit or m.pos not in CONTENT_POS or m.lemma in IGNORED_LEMMAS:
            continue
        if _classify(m) in ("name", "numeral", "homograph"):
            # A homograph (plan 213) has its cards; the breakdown names
            # neither rather than guess which.
            continue
        # The point's own word (余儀 in 〜を余儀なくされる) or a word the
        # point builds (支えあう).
        if m.surface in pattern or any(s in m.surface for s in built):
            continue
        out.append(m.lemma)
    return out


def tagged_above(jp: str, level: str, pattern: str) -> list[tuple[str, str]]:
    """Words written in kanji that the breakdown tags above `level` --
    what a learner reading the chips sees as a word their level has not
    reached, whatever difficulty.report's vocab gate let through (it
    passes a word that splits into easier ones: 問い合わせ, 引っ越し).
    Not the pieces of a word (a prefix, a suffix, a particle), a counter
    after a number (何度, 三台), nor the point's own words (乗りこむ for
    〜こむ). A word spelled in kana is left out: the deck files a few
    everyday ones under a rare kanji at a high level (すぐ under 直ぐ,
    N1), and the chip on those is the deck's to put right."""
    from study import difficulty as D
    from study.analysis import analyze_local
    from study.grammar_match import stems
    from study.level_mix import _FUNCTION_POS

    built = [s for s in stems(pattern) if s]
    out = []
    tokens = analyze_local(jp)["tokens"]
    for i, tok in enumerate(tokens):
        match = tok.get("vocab_match") or {}
        found = match.get("level")
        if not found or match.get("pool") or tok.get("pos") in _FUNCTION_POS:
            continue
        surface = tok["surface"]
        if D.rank(found) <= D.rank(level) or not any("一" <= c <= "鿿" for c in surface):
            continue
        before = tokens[i - 1]["surface"] if i else ""
        if _is_numeral(before) or before in ("何", "数"):
            continue
        if surface in pattern or any(s in surface for s in built):
            continue
        out.append((surface, found))
    return out


def focus_card(level: str, focus: str) -> str | None:
    """The deck card a rating of this row is scheduled on (unprefixed),
    resolved the way routes/reading's result does it."""
    from study.card_lookup import vocab_card_id_for_word

    card = vocab_card_id_for_word({"kanji": focus, "kana": "", "level": level}, "_")
    return card.split(":", 1)[1] if card else None


def row_problems(level: str, row: dict, catalogue: set[str] | None = None) -> list[str]:
    """Everything wrong with one row, as human-readable lines -- the
    rules in the module docstring. Split out of problems() so a row can
    be checked before it enters the bank (scripts/reading_bank_report
    --check)."""
    from study import difficulty as D
    from study import grammar_detect, morphology
    from study.grammar_match import contains_pattern, verifiable
    from study.level_mix import words_at_level

    catalogue = patterns_for(level) if catalogue is None else catalogue
    out: list[str] = []
    jp, pattern = row["jp"], row.get("grammar", "")
    for lang in ("en", "fr"):
        if not row.get(lang, "").strip():
            out.append(f"no {lang} translation")
    if pattern not in catalogue:
        out.append(f"{pattern!r} is not a {level} point")
    elif verifiable(pattern) and not contains_pattern(jp, pattern):
        out.append(f"does not contain {pattern!r}")
    # The point's own characters are exempt from the kanji gate --
    # see difficulty.report's allow_kanji.
    verdict = D.report(jp, level, allow_kanji=pattern)
    # And its own words from the vocab gate, for the same reason: 〜を契機に
    # is an N2 point spelled with 契機, which the deck files at N1.
    verdict["vocab"] = [(word, lv) for word, lv in verdict["vocab"] if word not in pattern]
    for key in ("kanji", "grammar", "vocab"):
        if verdict[key]:
            out.append(f"{key} above {level}: {verdict[key]}")
    if verdict["too_long"]:
        out.append(f"{verdict['too_long']} chars, cap is {D.MAX_CHARS[level]}")

    if level not in GRADED_LEVELS or not morphology.MORPHOLOGY_AVAILABLE:
        return out
    # The breakdown numbers the point for the learner; where the
    # detector has proved itself on the point, it must find it here.
    if pattern in catalogue and grammar_detect.can_find(pattern):
        if pattern not in {p for p, *_ in D.points_in(jp)}:
            out.append(f"the detector does not find {pattern!r}")
    words = words_at_level(jp, level, pattern)
    if len(words) < LEVEL_WORDS_MIN:
        named = ", ".join(w["kanji"] or w["kana"] for w in words) or "none"
        out.append(f"{len(words)} {level} words ({named}), at least {LEVEL_WORDS_MIN} wanted")
    card = focus_card(level, row.get("focus", ""))
    if card is None:
        out.append(f"focus {row.get('focus')!r} is no deck card")
    elif card not in {w["raw_id"] for w in words}:
        out.append(f"focus {row.get('focus')!r} ({card}) is not one of the sentence's {level} words")
    off = off_deck_words(jp)
    if off:
        out.append(f"words the deck does not teach: {off}")
    gaps = deck_gaps(jp, pattern)
    if gaps:
        out.append(f"words with no card, by the vocab audit: {gaps}")
    above = tagged_above(jp, level, pattern)
    if above:
        out.append(f"words the breakdown tags above {level}: {above}")
    return out


def problems() -> list[str]:
    """Everything wrong with the bank, as human-readable lines.

    Lives here rather than only in the test so the bank can be checked
    from a shell while it is being written -- which is how it was
    written. Empty means every sentence passes every rule in the module
    docstring.
    """
    out: list[str] = []
    for level, rows in BY_LEVEL.items():
        catalogue = patterns_for(level)
        for i, row in enumerate(rows):
            for line in row_problems(level, row, catalogue):
                out.append(f"{level}[{i}] {row['jp']}: {line}")
    return out
